import java.util.function.*;
import java.util.List;
import java.util.ArrayList;

public class FunctionalPipelineDemo {
    public static void main(String[] args) {
        Supplier<List<String>> listSupplier = ArrayList::new;
        Consumer<String> logger = str -> System.out.println("Processing: " + str);
        Predicate<String> lengthFilter = s -> s != null && s.length() > 3;
        UnaryOperator<String> upperCaseTransformer = String::toUpperCase;

        BiFunction<Integer, String, String> indexFormatter = (idx, str) -> idx + ": " + str;

        List<String> rawData = List.of("io", "nio", "exception", "handling");
        List<String> processed = listSupplier.get();

        int index = 1;
        for (String item : rawData) {
            if (lengthFilter.test(item)) {
                String transformed = upperCaseTransformer.apply(item);
                logger.accept(transformed);
                processed.add(indexFormatter.apply(index++, transformed));
            }
        }
    }
}
